import numpy as np

class AdaptiveCoordinateDirectionSearch:
    def __init__(self, budget=10000, dim=10, alpha=0.3, beta=0.7):
        self.budget = budget
        self.dim = dim
        self.alpha = alpha  # local exploration weight
        self.beta = beta    # random direction weight
        self.x_opt = None
        self.f_opt = np.inf
        self.x_best = None
        self.f_best = np.inf
        self.x_prev = None
        self.f_prev = np.inf

    def __call__(self, func):
        for i in range(self.budget):
            if i == 0 or np.random.rand() < 0.1:
                x = np.random.uniform(-5.0, 5.0, self.dim)
            else:
                if np.random.rand() < self.alpha:
                    x = self.x_prev.copy()
                    j = np.random.randint(self.dim)
                    x[j] += np.random.uniform(-1.0, 1.0)
                else:
                    x = self.x_prev.copy()
                    for j in range(self.dim):
                        x[j] += np.random.uniform(-5.0, 5.0) if self.x_prev[j] == self.x_best[j] else np.random.uniform(-self.beta, self.beta)

            f = func(x)
            if f < self.f_opt:
                self.x_opt = x.copy()
                self.f_opt = f
            if f < self.f_best:
                self.f_best = f
                self.x_best = x.copy()
            self.x_prev = self.x_opt.copy()
            self.f_prev = self.f_opt

        return self.x_opt, self.f_opt
